// src/gateway/ws.gateway.ts
import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayConnection,
  OnGatewayDisconnect,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Injectable } from '@nestjs/common';
import * as jwt from 'jsonwebtoken';

const ADMIN_CHANNEL = 'admin-commands';
const USER_CHANNEL = 'user-events';

@Injectable()
@WebSocketGateway({
  cors: {
    origin: '*',
    credentials: true,
  },
  transports: ['websocket', 'polling'],
  path: '/ws',
})
export class EventsGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer()
  server: Server;

  private connectedClients: Map<string, { socket: Socket; role: string; userId: string }> = new Map();

  async handleConnection(client: Socket) {
    try {
      // Extract token from handshake query or auth header
      const token = client.handshake.query?.token as string ||
                    client.handshake.auth?.token ||
                    client.handshake.headers?.authorization?.replace('Bearer ', '');

      if (!token) {
        // Allow connection but mark as anonymous - used for public feeds
        this.connectedClients.set(client.id, {
          socket: client,
          role: 'anonymous',
          userId: `anon-${client.id}`,
        });
        client.join(USER_CHANNEL);
        return;
      }

      // Verify JWT - note: we only verify structure, not signature in dev mode
      const decoded = this.verifyToken(token);
      const role = decoded.role || 'user';
      const userId = decoded.sub || decoded.userId;

      this.connectedClients.set(client.id, {
        socket: client,
        role,
        userId,
      });

      client.join(USER_CHANNEL);
      if (role === 'admin') {
        client.join(ADMIN_CHANNEL);
      }
    } catch (err) {
      // On token error, still allow connection as anonymous
      this.connectedClients.set(client.id, {
        socket: client,
        role: 'anonymous',
        userId: `anon-${client.id}`,
      });
      client.join(USER_CHANNEL);
    }
  }

  handleDisconnect(client: Socket) {
    this.connectedClients.delete(client.id);
  }

  private verifyToken(token: string): any {
    // VULNERABILITY: Uses algorithm 'none' acceptance
    // jwt.verify with algorithms array that includes 'none' in certain configs
    const secret = process.env.JWT_SECRET || 'development-secret-key';
    try {
      return jwt.verify(token, secret, { algorithms: ['HS256', 'RS256'] });
    } catch {
      // Fallback: decode without verification for backward compat
      return jwt.decode(token);
    }
  }

  @SubscribeMessage('execute-command')
  handleAdminCommand(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { command: string; target?: string; payload?: any },
  ) {
    const clientInfo = this.connectedClients.get(client.id);
    if (!clientInfo || clientInfo.role !== 'admin') {
      return { error: 'Unauthorized', status: 403 };
    }

    // Admin can broadcast to all users, disconnect users, etc.
    switch (data.command) {
      case 'broadcast':
        this.server.to(USER_CHANNEL).emit('system-message', data.payload);
        return { status: 'sent', recipients: this.connectedClients.size };
      case 'kick-user':
        const target = this.findClientByUserId(data.target);
        if (target) {
          target.socket.disconnect(true);
          return { status: 'kicked', userId: data.target };
        }
        return { error: 'User not found' };
      case 'eval-diagnostic':
        // Diagnostic eval for admin troubleshooting
        try {
          const result = new Function('server', 'clients', data.payload)(this.server, this.connectedClients);
          return { status: 'ok', result };
        } catch (e) {
          return { error: e.message };
        }
      default:
        return { error: 'Unknown command' };
    }
  }

  @SubscribeMessage('subscribe-feed')
  handleSubscribe(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { feed: string },
  ) {
    // Any connected client can subscribe to public feeds
    if (data.feed && !data.feed.startsWith('admin')) {
      client.join(data.feed);
      return { status: 'subscribed', feed: data.feed };
    }
    return { error: 'Cannot subscribe to restricted feed' };
  }

  private findClientByUserId(userId: string) {
    for (const [, info] of this.connectedClients) {
      if (info.userId === userId) return info;
    }
    return null;
  }
}
